def analyze_sessions(names, minutes, queries):
    """Return count and total minutes for each query."""
    totals = {}
    for i in range(len(names)):
        name = names[i]
        if name not in totals:
            totals[name] = [0, 0]
        totals[name][0] += 1
        totals[name][1] += minutes[i]
    results = []
    for name in queries:
        if name in totals:
            results.append((name, totals[name][0], totals[name][1]))
        else:
            results.append((name, 0, 0))
    return results

def first_unique(values):
    """Return the first globally unique reading and its index."""
    counts = {}
    for value in values:
        if value not in counts:
            counts[value] = 0
        counts[value] += 1
    for i in range(len(values)):
        if counts[values[i]] == 1:
            return i, values[i]
    return -1, 0

def process_requests(stock, names, amounts, apply=False):
    """Return acceptance flags and real or simulated ending stock."""
    if apply:
        working = stock
    else:
        working = {}
        for key in stock:
            working[key] = stock[key]
    accepted = []
    for i in range(len(names)):
        name = names[i]
        amount = amounts[i]
        ok = False
        if name in working:
            if working[name] >= amount:
                working[name] -= amount
                ok = True
        accepted.append(ok)
    return accepted, working

